content.arguments:
{"command":""=== JDK candidates ==="
$jdkPaths = @("C:\Program Files\Java","C:\Program Files\Eclipse Adoptium","C:\Program Files\Microsoft","C:\Program Files\Amazon Corretto","C:\Program Files\Zulu","C:\Program Files (x86)\Java","D:\Java","D:\Program Files\Java","D:\jdk","C:\jdk")
foreach ($p in $jdkPaths) { if (Test-Path $p) { Get-ChildItem $p -Directory -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName } }
"=== mysql / redis executables on PATH or common dirs ==="
foreach ($n in @("mysql","mysqld","redis-server","redis-cli","mariadb")) {
  $c = Get-Command $n -ErrorAction SilentlyContinue
  if ($c) { "PATH: $n -> $($c.Source)" } else { "PATH: $n -> NOT FOUND" }
}
foreach ($p in @("C:\Program Files\MySQL","C:\ProgramData\MySQL","D:\MySQL","D:\Program Files\MySQL","C:\Redis","D:\Redis","C:\Program Files\Redis")) { if (Test-Path $p) { "DIR: $p"; Get-ChildItem $p -ErrorAction SilentlyContinue | Select-Object -First 8 -ExpandProperty FullName } }
"=== package managers ==="
foreach ($n in @("choco","scoop","winget")) { $c = Get-Command $n -ErrorAction SilentlyContinue; if ($c) { "PATH: $n -> $($c.Source)" } else { "PATH: $n -> NOT FOUND" } }
"=== running services (mysql/redis) ==="
Get-Service -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'mysql|redis|maria' } | Select-Object Name,Status,DisplayName | Format-Table -AutoSize | Out-String -Width 160
"=== Maven repo present? ==="
if (Test-Path "$env:USERPROFILE\.m2\repository") { "m2 repo exists: " + (Get-ChildItem "$env:USERPROFILE\.m2\repository" -Directory | Measure-Object).Count + " groups" } else { "no m2 repo" }","description":"Scan for JDK 17, MySQL, Redis, package managers"}

