content.arguments:
{"command":""=== Redis dir ==="
Get-ChildItem "D:\G\Redis" -File | Select-Object Name,Length | Format-Table -AutoSize | Out-String -Width 120
"=== requirepass lines ==="
Get-ChildItem "D:\G\Redis" -Filter "*.conf" | ForEach-Object {
  "--- $($_.Name) ---"
  Select-String -LiteralPath $_.FullName -Pattern "^\s*(requirepass|port|bind|maxmemory)" | ForEach-Object { $_.Line }
}","description":"Find Redis password and port config"}

{"command":""=== probe mysql download endpoints ==="
foreach ($u in @(
  "https://cdn.mysql.com/Downloads/MySQL-8.4/mysql-8.4.6-winx64.zip",
  "https://dev.mysql.com/get/Downloads/MySQL-8.4/mysql-8.4.6-winx64.zip",
  "https://cdn.mysql.com/Downloads/MySQL-8.0/mysql-8.0.43-winx64.zip"
)) {
  try {
    $r = Invoke-WebRequest -Uri $u -Method Head -TimeoutSec 25 -MaximumRedirection 5 -ErrorAction Stop
    "OK  $($r.StatusCode)  len=$($r.Headers.'Content-Length')  $u"
  } catch { "ERR $($_.Exception.Message.Substring(0,[Math]::Min(90,$_.Exception.Message.Length)))  $u" }
}","description":"Probe MySQL ZIP download URLs","timeoutMs":120000}

