content.arguments:
{"command":"$versions = @("8.4.9","8.4.8","8.4.7","8.4.6","8.4.5","8.4.4","8.4.3","8.4.2","8.4.1","8.4.0","8.0.44","8.0.43","8.0.42","8.0.41","8.0.40")
foreach ($v in $versions) {
  $major = if ($v -like "8.4*") { "8.4" } else { "8.0" }
  $u = "https://cdn.mysql.com/Downloads/MySQL-$major/mysql-$v-winx64.zip"
  try {
    $r = Invoke-WebRequest -Uri $u -Method Head -TimeoutSec 20 -ErrorAction Stop
    "OK   $v  len=$([math]::Round([int64]$r.Headers.'Content-Length'/1MB,1))MB"
  } catch {
    $code = $_.Exception.Response.StatusCode.value__
    "MISS $v  ($code)"
  }
}","description":"Probe MySQL ZIP versions on CDN","timeoutMs":300000}

