content.arguments:
{"command":"$mirrors = @(
 "https://mirrors.tuna.tsinghua.edu.cn/mysql/downloads/MySQL-8.4/",
 "https://mirrors.ustc.edu.cn/mysql-ftp/Downloads/MySQL-8.4/",
 "https://mirrors.aliyun.com/mysql/MySQL-8.4/",
 "https://mirrors.cloud.tencent.com/mysql/downloads/MySQL-8.4/"
)
foreach ($m in $mirrors) {
  try {
    $r = Invoke-WebRequest -Uri $m -TimeoutSec 25 -ErrorAction Stop
    $zips = ([regex]::Matches($r.Content,'href="(mysql-8\.4\.\d+-winx64\.zip)"') | ForEach-Object { $_.Groups[1].Value }) | Sort-Object -Unique
    "OK   $m"
    if ($zips) { $zips | Select-Object -Last 6 | ForEach-Object { "        $_" } } else { "        (no winx64.zip links found)" }
  } catch { "ERR  $m  -> $($_.Exception.Message.Substring(0,[Math]::Min(70,$_.Exception.Message.Length)))" }
}","description":"List MySQL 8.4 zips on Chinese mirrors","timeoutMs":180000}

