@Configuration
public class OpenApiConfig {

    private static final String BEARER = "bearerAuth";

    @Bean
    public OpenAPI weBoxOpenApi() {
        return new OpenAPI()
                .info(new Info()
                        .title("WeBox API")
                        .version("1.0.0")
                        .description("""
