                .orElseThrow(() -> new BusinessException(ErrorCode.UNAUTHENTICATED));
    }

    private AuthResponse issue(User user) {
        return AuthResponse.bearer(jwtService.issue(user), jwtService.ttlSeconds(), UserResponse.from(user));
    }
}
