    public MenuCacheService(StringRedisTemplate redis, ObjectMapper objectMapper, WeBoxProperties properties) {
        this.redis = redis;
        this.objectMapper = objectMapper;
        this.ttl = Duration.ofMinutes(properties.menuCache().ttlMinutes());
    }

