                try (Cursor<byte[]> cursor = connection.keyCommands().scan(options)) {
                    while (cursor.hasNext()) {
                        batch.add(cursor.next());
                        if (batch.size() >= SCAN_BATCH) {
                            total += nullSafe(connection.keyCommands().del(batch.toArray(new byte[0][])));
                            batch.clear();
                        }
                    }
                }
                if (!batch.isEmpty()) {
                    total += nullSafe(connection.keyCommands().del(batch.toArray(new byte[0][])));
                }
                return total;
            });
