public final class CartRuleValidator {
    public record Selection(String groupName, String optionName, BigDecimal priceDelta) {}

    public static List<Selection> resolveSelections(Dish dish, Set<Long> requestedOptionIds) {
        Set<Long> requested = requestedOptionIds == null ? Set.of() : requestedOptionIds;

        // collect all option ids of this dish
        Map<Long, DishOption> allOptions = ...;

        // unknown option ids → OPTION_INVALID
        for (Long id : requested) if (!allOptions.containsKey(id)) throw OPTION_INVALID;

        List<Selection> selections = new ArrayList<>();
        for (DishOptionGroup group : dish.getOptionGroups()) {
            List<DishOption> chosen = group.getOptions().stream().filter(o -> requested.contains(o.getId())).toList();
            if (group.isRequired() && chosen.isEmpty()) throw OPTION_INVALID;
            if (group.getSelectionType() == SINGLE && chosen.size() > 1) throw OPTION_INVALID;
            for (DishOption o : chosen) {
                if (!o.isAvailable()) throw OPTION_INVALID;
                selections.add(new Selection(group.getName(), o.getName(), o.getPriceDelta()));
            }
        }
        return selections;
    }

    public static void validateItemCount(int totalQuantity, int max) {
        if (totalQuantity > max) throw new BusinessException(ORDER_SIZE_EXCEEDED);
        if (totalQuantity <= 0) throw new BusinessException(VALIDATION_FAILED, "Your cart is empty.");
    }
}
