{"command":"$OutputEncoding = [System.Text.Encoding]::UTF8
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$base = "http://localhost:8080"
function Post($path, $headers, $bodyJson) {
  try {
    $r = Invoke-WebRequest -Method Post -Uri "$base$path" -Headers $headers -ContentType "application/json; charset=utf-8" -Body $bodyJson -UseBasicParsing
    "STATUS $([int]$r.StatusCode)"; $r.Content
  } catch {
    $resp = $_.Exception.Response
    $sr = New-Object System.IO.StreamReader($resp.GetResponseStream())
    "STATUS $([int]$resp.StatusCode)"; $sr.ReadToEnd()
  }
}
$email = "dbg.$([guid]::NewGuid().ToString('N').Substring(0,6))@example.com"
$reg = Invoke-RestMethod -Method Post -Uri "$base/api/auth/register" -ContentType "application/json" -Body (@{email=$email;password="Passw0rd123";displayName="Dbg"}|ConvertTo-Json)
$tok = $reg.data.token
$h = @{ Authorization = "Bearer $tok" }
$dates = Invoke-RestMethod -Uri "$base/api/menu/dates" -Headers $h
$today = $dates.data[0]
"today=$today  type=$($today.GetType().Name)"

$body = @{ items=@(@{dishId=1;quantity=2;optionIds=@()}); deliveryDate="$today"; mealSlot="Lunch"; deliveryAddress="Desk 1" } | ConvertTo-Json -Depth 6 -Compress
"--- body: $body"

$key = [guid]::NewGuid().ToString()
$h1 = @{ Authorization = "Bearer $tok"; "Idempotency-Key" = $key }
"--- 1st submit"; Post "/api/orders" $h1 $body
"--- 2nd submit (same key)"; Post "/api/orders" $h1 $body
"--- preview WITH deliveryAddress"; Post "/api/orders/checkout-preview" $h @{ items=@(@{dishId=1;quantity=3;optionIds=@()},@{dishId=2;quantity=3;optionIds=@()}); deliveryDate="$today"; mealSlot="Lunch"; deliveryAddress="Desk 1" } | Out-Null
$previewBody = @{ items=@(@{dishId=1;quantity=3;optionIds=@()},@{dishId=2;quantity=3;optionIds=@()}); deliveryDate="$today"; mealSlot="Lunch" } | ConvertTo-Json -Depth 6 -Compress
Post "/api/orders/checkout-preview" $h $previewBody","description":"Debug idempotency replay and preview failures","timeoutMs":120000}

