Select-String -LiteralPath "backend\.mvn\wrapper\maven-wrapper.properties" -Pattern 'distributionUrl' | ForEach-Object { "  $($_.Line.Trim())" }","description":"Check whether the project depends on machine-local files","timeoutMs":300000}

