{"command":"$OutputEncoding = [System.Text.Encoding]::UTF8
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
Set-Location "D:\G\MyRep\webox"

"=== build outputs present on disk (must NOT be uploaded) ==="
$jar = Get-Item "backend\target\webox-backend-1.0.0.jar" -ErrorAction SilentlyContinue
if ($jar) { "backend\target\webox-backend-1.0.0.jar   {0} MB" -f [math]::Round($jar.Length/1MB,1) }
$nm = Get-ChildItem "frontend\node_modules" -Recurse -File -ErrorAction SilentlyContinue
if ($nm) { "frontend\node_modules\               {0} MB / {1} files" -f [math]::Round(($nm | Measure-Object Length -Sum).Sum/1MB,1), $nm.Count }
$dist = Get-ChildItem "frontend\dist" -Recurse -File -ErrorAction SilentlyContinue
if ($dist) { "frontend\dist\                      {0} MB" -f [math]::Round(($dist | Measure-Object Length -Sum).Sum/1MB,2) }

"=== is there any .jar / .zip anywhere in the source tree? ==="
$archives = Get-ChildItem -Recurse -File -Include *.jar,*.zip,*.war -ErrorAction SilentlyContinue |
  Where-Object { $_.FullName -notmatch '\\node_modules\\|\\target\\' }
if ($archives) { $archives | ForEach-Object { "  $($_.FullName.Replace((Get-Location).Path+'\',''))  {0} MB" -f [math]::Round($_.Length/1MB,2) } } else { "  none - the source tree contains no archives" }

"=== binary assets that MUST be uploaded (part of the app) ==="
$imgs = Get-ChildItem "backend\src\main\resources\static\dishes" -File -ErrorAction SilentlyContinue
"backend\src\main\resources\static\dishes\  {0} files / {1} MB  <- required, the SPA serves these" -f $imgs.Count, [math]::Round(($imgs | Measure-Object Length -Sum).Sum/1MB,2)

"=== the two files that make a source-only upload reproducible ==="
foreach ($f in @('backend\pom.xml','frontend\package-lock.json','backend\.mvn\wrapper\maven-wrapper.properties')) {
  $i = Get-Item $f -ErrorAction SilentlyContinue
  if ($i) { "{0,-52} {1} KB" -f $f, [math]::Round($i.Length/1KB,1) } else { "{0,-52} MISSING" -f $f }
}","description":"Check build outputs, archives, and required binary assets"}

